def transform(grid):
    # Candidate: rays from each 3x3 green target, along the axis perpendicular to its 2-grid line.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and all(grid[rr][cc]==3 for rr in range(r-1,r+2) for cc in range(c-1,c+2) if (rr,cc)!=(r,c)):
                centers.append((r,c))
    for r,c in centers:
        # Grid-line orientation: if the center's column is a full 2 separator, emit horizontally;
        # otherwise emit vertically. Paint only empty cells; preserve symbols and dividers.
        vertical = sum(grid[rr][c]==2 for rr in range(h)) > sum(grid[r][cc]==2 for cc in range(w))
